<?php get_header(); ?><main id="main" class="section"><div class="container"><header class="page-header"><span class="sa-kicker">Catalog search</span><h1>Results for “<?php echo esc_html( get_search_query() ); ?>”</h1></header><?php if ( have_posts() && function_exists( 'woocommerce_product_loop_start' ) ) : woocommerce_product_loop_start(); while ( have_posts() ) : the_post(); wc_get_template_part( 'content', 'product' ); endwhile; woocommerce_product_loop_end(); the_posts_pagination(); else : ?><div class="empty-state"><h2>No matching parts yet</h2><p>Try a SKU, category, or a shorter vehicle name.</p><a class="button button--accent" href="<?php echo esc_url( sa_wc_page_url( 'shop' ) ); ?>">Browse all parts</a></div><?php endif; ?></div></main><?php get_footer(); ?>
